@layer ds.recipes {
  /* button-press */
  [data-style='studio'] [data-ds='button'] {
    --_button-press-scale: 1;
  }
  /* button-press */
  [data-style='studio'] [data-ds='icon-button'] {
    --_button-press-scale: 1;
  }
  /* button-press */
  [data-style='studio'] [data-ds='toggle-button'] {
    --_button-press-scale: 1;
  }
  /* button-press */
  [data-style='studio'] [data-ds='copy-button'] {
    --_button-press-scale: 1;
  }
  /* check-draw */
  [data-style='studio'] [data-ds='checkbox'] {
    --_checkbox-duration: 0s;
    --_checkbox-duration-out: 0s;
  }
  /* switch-stretch */
  [data-style='studio'] [data-ds='switch'] {
    --_switch-stretch: 1;
    --_switch-duration: var(--ds-duration-base);
    --_switch-ease: var(--ds-ease-default);
  }
  /* focus-glow */
  [data-style='studio'] [data-ds='input'] {
    --_input-duration-in: 0s;
    --_input-duration-out: 0s;
    --_input-enter-scale: 1;
  }
  /* focus-glow */
  [data-style='studio'] [data-ds='password-field'] {
    --_password-field-duration-in: 0s;
    --_password-field-duration-out: 0s;
    --_password-field-enter-scale: 1;
  }
  /* focus-glow */
  [data-style='studio'] [data-ds='otp-field'] {
    --_otp-field-duration-in: 0s;
    --_otp-field-duration-out: 0s;
    --_otp-field-enter-scale: 1;
  }
  /* focus-glow */
  [data-style='studio'] [data-ds='number-field'] {
    --_number-field-duration-in: 0s;
    --_number-field-duration-out: 0s;
    --_number-field-enter-scale: 1;
  }
  /* menu-origin */
  [data-style='studio'] [data-ds='dropdown-menu'] {
    --_menu-enter-scale: 1;
  }
  /* menu-origin */
  [data-style='studio'] [data-ds='context-menu'] {
    --_menu-enter-scale: 1;
  }
  /* menu-origin */
  [data-style='studio'] [data-ds='popover'] {
    --_popover-enter-scale: 1;
  }
  /* tooltip-rise */
  [data-style='studio'] [data-ds='tooltip'] {
    --_tooltip-shift: 0px;
  }
  /* toast-enter */
  [data-style='studio'] [data-ds='toast'] {
    --_toast-enter-y: 0px;
    --_toast-enter-scale: 1;
  }
  /* toast-swipe */
  [data-style='studio'] [data-ds='toast'] {
    --_toast-duration: 0s;
    --_toast-swipe-x: 0%;
    --_toast-swipe-y: 0%;
  }
  /* dialog-spring */
  [data-style='studio'] [data-ds='dialog'] {
    --_dialog-enter-y: 0px;
    --_dialog-enter-scale: 1;
  }
  /* dialog-spring */
  [data-style='studio'] [data-ds='alert-dialog'] {
    --_dialog-enter-y: 0px;
    --_dialog-enter-scale: 1;
  }
  /* sheet-spring */
  [data-style='studio'] [data-ds='sheet'] {
    --_dialog-slide: 0%;
    --_dialog-enter-opacity: 0;
    --_dialog-drag-duration: 0s;
  }
  /* sheet-spring */
  [data-style='studio'] [data-ds='drawer'] {
    --_dialog-slide: 0%;
    --_dialog-enter-opacity: 0;
  }
  /* accordion-reveal */
  [data-style='studio'] [data-ds='accordion'] {
    --_accordion-duration: 0s;
  }
  /* skeleton-swap */
  [data-style='studio'] [data-ds='skeleton'] {
    --_skeleton-loops: 0;
  }
  /* slider-pull */
  [data-style='studio'] [data-ds='slider'] {
    --_slider-lift: 1;
  }
  /* slider-pull */
  [data-style='studio'] [data-ds='range-slider'] {
    --_slider-lift: 1;
  }
}
